import { Rectangle } from 'pixi.js';
import { BlendLevel, ICoreSettings, IReelSettings, ISymbolSettings } from '../../../types';

const DEFAULT_CORE_SETTINGS: ICoreSettings = ({
    topOffset: 1,
    bottomOffset: 1,
    viewMaskYOffset: 0,
    allowZIndexSymbolSorting: false,
    recursiveTransforming: true,
    snapshotInjection: false
});

const DEFAULT_SYMBOL_SETTINGS: ISymbolSettings = ({
    frameTransfrom: new Rectangle(0, 0, 200, 156)
});

const DEFAULT_REEL_SETTINGS: IReelSettings = ({
    bounceSettings: {
        elasticStopIntensity: 0.98,
        elasticStopDuration: 0.8,
        elasticBounceAmplitude: 1,
        elasticBouncePeriod: 0.3,
    },
    reelStartDelay: 0,
    rollbackSpeed: -10,
    symbolVerticalPadding: 0,
    stoppingBlendMode: BlendLevel.full,
    speedSettings: {
        acceleration: {
            limit: 1,
            steps: [],
        },
        deceleration: {
            limit: 1,
            steps: [],
        },
    }
});

export class GRSettings {

    private _coreSettings: ICoreSettings;
    private _reelSettings: IReelSettings;
    private _symbolSettings: ISymbolSettings;

    constructor() {
        this._coreSettings = DEFAULT_CORE_SETTINGS;
        this._symbolSettings = DEFAULT_SYMBOL_SETTINGS;
        this._reelSettings = DEFAULT_REEL_SETTINGS;
    }

    public updateCoreSettings(settings: ICoreSettings | Partial<ICoreSettings>): void {
        this._coreSettings = { ...this._coreSettings, ...settings };
    }

    public updateSymbolSettings(settings: IReelSettings | Partial<ISymbolSettings>): void {
        this._symbolSettings = { ...this._symbolSettings, ...settings };
    }

    public updateReelSettings(settings: IReelSettings | Partial<IReelSettings>): void {
        this._reelSettings = { ...this._reelSettings, ...settings };
    }

    public get coreSettings(): ICoreSettings {
        return this._coreSettings;
    }

    public get symbolSettings(): ISymbolSettings {
        return this._symbolSettings;
    }

    public get reelSettings(): IReelSettings {
        return this._reelSettings;
    }
}